async function handleLibrarySearch(request2, env2) {
  let body;
  try {
    body = await request2.json();
  } catch {
    return jsonErr("Invalid JSON", 400);
  }
  const { query, approach, exclude_approach, language, topK = 5 } = body;
  if (!query)
    return jsonErr("Missing query", 400);
  if (!env2.AI || !env2.VECTOR_INDEX || !env2.DB)
    return jsonErr("Worker bindings not configured. Need: AI, VECTOR_INDEX, DB", 500);
  try {
    const embedResult = await env2.AI.run("@cf/baai/bge-m3", { text: [query] });
    if (!embedResult?.data?.[0])
      return jsonErr("Embedding generation failed", 500);
    const fetchK = exclude_approach ? Math.min(topK * 3, 50) : Math.min(topK, 20);
    const vq = { topK: fetchK, returnMetadata: "all" };
    const matches = await env2.VECTOR_INDEX.query(embedResult.data[0], vq);
    if (!matches?.matches?.length)
      return json({ results: [], query, message: "No matches found" });
    const ids = matches.matches.map((m) => m.id);
    const { results: chunks } = await env2.DB.prepare(
      `SELECT id, book_title, author, chapter, page_number, content, approach, language FROM chunks WHERE id IN (${ids.map(() => "?").join(",")})`
    ).bind(...ids).all();
    let results = matches.matches.map((m) => {
      const c = chunks.find((c2) => c2.id === m.id);
      return {
        id: m.id,
        score: m.score,
        book_title: c?.book_title || "?",
        author: c?.author || "?",
        chapter: c?.chapter || null,
        page: c?.page_number || null,
        approach: c?.approach || "?",
        language: c?.language || "?",
        content: c?.content || "[non trouv\xE9]"
      };
    });
    if (language)
      results = results.filter((r) => r.language === language);
    if (exclude_approach) {
      const ex = Array.isArray(exclude_approach) ? exclude_approach : [exclude_approach];
      results = results.filter((r) => !ex.includes(r.approach));
    }
    results = results.slice(0, topK);
    return json({ query, results, total_matches: results.length });
  } catch (err2) {
    return jsonErr(err2.message, 500);
  }
}
