// WEB-CONSULT — Recherche web filtrée + fiabilité
// © C Concept&Dev — Christophe Bonnet — Mars 2026
// PubMed E-utilities + Semantic Scholar API
// ═══════════════════════════════════════════════════════════════════════════════

const TRUSTED_DOMAINS = {
  high: [
    'pubmed.ncbi.nlm.nih.gov','ncbi.nlm.nih.gov',
    'semanticscholar.org','api.semanticscholar.org',
    'cochrane.org','cochranelibrary.com',
    'who.int','has-sante.fr',
    'apa.org','psycnet.apa.org','cairn.info'
  ],
  medium: [
    'scholar.google.com','researchgate.net',
    'springer.com','wiley.com','tandfonline.com',
    'elsevier.com','sciencedirect.com',
    'frontiersin.org','mdpi.com','bps.org.uk',
    'em-consulte.com','vidal.fr'
  ],
  excluded_patterns: [
    'forum','blog','reddit','quora','yahoo',
    'coaching','magnetisme','reiki',
    'facebook','instagram','tiktok','youtube',
    'amazon','fnac','ebay'
  ]
};

function scoreReliability(result) {
  let score = 0;
  const urlLower = (result.url || '').toLowerCase();
  if (TRUSTED_DOMAINS.high.some(d => urlLower.includes(d))) score += 40;
  else if (TRUSTED_DOMAINS.medium.some(d => urlLower.includes(d))) score += 20;
  else score += 5;
  if (result.date) {
    const year = parseInt(result.date);
    if (!isNaN(year)) {
      const age = new Date().getFullYear() - year;
      if (age < 2) score += 20;
      else if (age < 5) score += 15;
      else if (age < 10) score += 10;
      else score += 5;
    }
  }
  if (result.isPeerReviewed) score += 25;
  if (result.isMeta) score += 20;
  if (result.isGuideline) score += 20;
  if (result.isCaseStudy) score += 15;
  if (result.isTextbook) score += 15;
  if (score >= 70) return 'high';
  if (score >= 40) return 'medium';
  return 'low';
}
__name(scoreReliability, "scoreReliability");

function explainReliability(result) {
  const parts = [];
  const urlLower = (result.url || '').toLowerCase();
  if (TRUSTED_DOMAINS.high.some(d => urlLower.includes(d))) parts.push('source haute fiabilité');
  else if (TRUSTED_DOMAINS.medium.some(d => urlLower.includes(d))) parts.push('source fiabilité moyenne');
  else parts.push('source non vérifiée');
  if (result.isPeerReviewed) parts.push('peer-reviewed');
  if (result.isMeta) parts.push('méta-analyse');
  if (result.isGuideline) parts.push('recommandation officielle');
  if (result.date) {
    const year = parseInt(result.date);
    if (!isNaN(year)) parts.push('publié ' + year);
  }
  return parts.join(', ');
}
__name(explainReliability, "explainReliability");

async function searchPubMed(query, language, maxResults) {
  try {
    // PAS de filtre langue — la littérature clinique est majoritairement en anglais
    // Chercher en toutes langues, le scoring de fiabilité pondère ensuite
    const searchUrl = 'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?' +
      'db=pubmed&term=' + encodeURIComponent(query) + '&retmax=' + (maxResults || 5) + '&retmode=json&sort=relevance';
    const searchResp = await fetch(searchUrl);
    if (!searchResp.ok) return [];
    const searchData = await searchResp.json();
    let ids = searchData.esearchresult?.idlist || [];

    // Retry avec query élargie si 0 résultats
    if (!ids.length && query.split(' ').length > 2) {
      const broader = query.split(' ').slice(0, 3).join(' '); // garder les 3 premiers termes
      const retryUrl = 'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?' +
        'db=pubmed&term=' + encodeURIComponent(broader) + '&retmax=' + (maxResults || 5) + '&retmode=json&sort=relevance';
      const retryResp = await fetch(retryUrl);
      if (retryResp.ok) {
        const retryData = await retryResp.json();
        ids = retryData.esearchresult?.idlist || [];
      }
    }

    if (!ids.length) return [];
    const summaryUrl = 'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi?' +
      'db=pubmed&id=' + ids.join(',') + '&retmode=json';
    const summaryResp = await fetch(summaryUrl);
    if (!summaryResp.ok) return [];
    const summaryData = await summaryResp.json();
    return Object.values(summaryData.result || {})
      .filter(r => r.uid)
      .map(r => {
        const pubtype = (r.pubtype || []).join(',').toLowerCase();
        return {
          title: r.title || '',
          source: 'PubMed',
          url: 'https://pubmed.ncbi.nlm.nih.gov/' + r.uid + '/',
          snippet: (r.title || '') + '. ' + (r.sortfirstauthor || '') + ' et al. ' + (r.fulljournalname || r.source || '') + '.',
          date: r.pubdate || '',
          language: (r.lang || []).includes('fre') ? 'fr' : 'en',
          isPeerReviewed: true,
          isMeta: pubtype.includes('meta-analysis') || (r.title||'').toLowerCase().includes('meta-analy'),
          isGuideline: pubtype.includes('guideline') || pubtype.includes('practice guideline'),
          isCaseStudy: pubtype.includes('case report'),
          isTextbook: false,
          type: 'article',
          pmid: r.uid
        };
      });
  } catch (e) {
    console.error('[WebConsult] PubMed error:', e.message);
    return [];
  }
}
__name(searchPubMed, "searchPubMed");

async function searchSemanticScholar(query, language, maxResults) {
  try {
    const fields = 'title,url,abstract,year,citationCount,journal,publicationTypes,externalIds';
    const ssUrl = 'https://api.semanticscholar.org/graph/v1/paper/search?' +
      'query=' + encodeURIComponent(query) + '&limit=' + (maxResults || 5) + '&fields=' + fields;
    const resp = await fetch(ssUrl, { headers: { 'User-Agent': 'CConceptDev-WebConsult/1.0' } });
    if (!resp.ok) return [];
    const data = await resp.json();
    return (data.data || []).map(paper => {
      const pubTypes = (paper.publicationTypes || []).map(t => t.toLowerCase());
      const titleLower = (paper.title || '').toLowerCase();
      return {
        title: paper.title || '',
        source: 'Semantic Scholar',
        url: paper.url || ('https://www.semanticscholar.org/paper/' + paper.paperId),
        snippet: (paper.abstract || paper.title || '').substring(0, 400),
        date: paper.year ? String(paper.year) : '',
        language: language || 'en',
        isPeerReviewed: !!paper.journal?.name,
        isMeta: pubTypes.includes('meta-analysis') || titleLower.includes('meta-analy') || titleLower.includes('systematic review'),
        isGuideline: pubTypes.includes('guideline') || titleLower.includes('guideline'),
        isCaseStudy: pubTypes.includes('case report') || titleLower.includes('case study'),
        isTextbook: false,
        type: 'article',
        citationCount: paper.citationCount || 0,
        doi: paper.externalIds?.DOI || null
      };
    });
  } catch (e) {
    console.error('[WebConsult] Semantic Scholar error:', e.message);
    return [];
  }
}
__name(searchSemanticScholar, "searchSemanticScholar");

async function searchGoogleScholar(query, language, maxResults, env2) {
  try {
    const apiKey = env2?.SERPAPI_KEY;
    if (!apiKey) { console.warn('[WebConsult] SERPAPI_KEY not configured'); return []; }
    const lang = language === 'fr' ? 'fr' : 'en';
    const url = 'https://serpapi.com/search.json?' +
      'engine=google_scholar' +
      '&q=' + encodeURIComponent(query) +
      '&hl=' + lang +
      '&num=' + (maxResults || 5) +
      '&api_key=' + apiKey;
    const resp = await fetch(url);
    if (!resp.ok) { console.warn('[WebConsult] SerpApi HTTP', resp.status); return []; }
    const data = await resp.json();
    return (data.organic_results || []).map(r => {
      const titleLower = (r.title || '').toLowerCase();
      const snippet = r.snippet || r.publication_info?.summary || r.title || '';
      const year = r.publication_info?.summary?.match(/(\d{4})/)?.[1] || '';
      const cited = r.inline_links?.cited_by?.total || 0;
      const link = r.link || r.resources?.[0]?.link || '';
      return {
        title: r.title || '',
        source: 'Google Scholar',
        url: link,
        snippet: snippet.substring(0, 400),
        date: year,
        language: lang,
        isPeerReviewed: !!year && cited > 0,
        isMeta: titleLower.includes('meta-analy') || titleLower.includes('systematic review'),
        isGuideline: titleLower.includes('guideline') || titleLower.includes('recommandation'),
        isCaseStudy: titleLower.includes('case report') || titleLower.includes('case study'),
        isTextbook: titleLower.includes('handbook') || titleLower.includes('textbook'),
        type: 'article',
        citationCount: cited,
        doi: null
      };
    });
  } catch (e) {
    console.error('[WebConsult] Google Scholar error:', e.message);
    return [];
  }
}
__name(searchGoogleScholar, "searchGoogleScholar");

async function searchCairn(query, language, maxResults) {
  try {
    const searchUrl = 'https://www.cairn.info/resultats_recherche.php?searchTerm=' + encodeURIComponent(query);
    const resp = await fetch(searchUrl, {
      headers: {
        'User-Agent': 'Mozilla/5.0 (compatible; CConceptDev-WebConsult/1.0)',
        'Accept': 'text/html',
        'Accept-Language': 'fr-FR,fr;q=0.9'
      }
    });
    if (!resp.ok) { console.warn('[WebConsult] Cairn HTTP', resp.status); return []; }
    const html = await resp.text();
    const results = [];
    // Parser les résultats Cairn — structure HTML : div.result-item ou article
    // Cairn utilise des blocs avec titre h2/h3, auteur, revue, année, résumé
    const itemRegex = /<(?:div|article)[^>]*class="[^"]*(?:result|search-item|pub-item)[^"]*"[^>]*>([\s\S]*?)(?=<(?:div|article)[^>]*class="[^"]*(?:result|search-item|pub-item)|$)/gi;
    const titleRegex = /<(?:h[23]|a)[^>]*class="[^"]*(?:titre|title)[^"]*"[^>]*>(?:<a[^>]*>)?\s*([\s\S]*?)\s*(?:<\/a>)?<\/(?:h[23]|a)>/i;
    const linkRegex = /<a[^>]*href="(\/(?:revue|article|livre)[^"]*)"[^>]*>/i;
    const authorRegex = /(?:class="[^"]*(?:auteur|author)[^"]*"[^>]*>|<span[^>]*class="[^"]*nom[^"]*"[^>]*>)\s*([\s\S]*?)\s*<\//i;
    const yearRegex = /(\b20[012]\d\b)/;
    const revueRegex = /class="[^"]*(?:revue|journal|source)[^"]*"[^>]*>\s*([\s\S]*?)\s*<\//i;
    const resumeRegex = /class="[^"]*(?:resume|abstract|description)[^"]*"[^>]*>\s*([\s\S]*?)\s*<\//i;

    let match;
    while ((match = itemRegex.exec(html)) !== null && results.length < (maxResults || 5)) {
      const block = match[1];
      const titleMatch = block.match(titleRegex);
      const linkMatch = block.match(linkRegex);
      if (!titleMatch) continue;
      const title = titleMatch[1].replace(/<[^>]*>/g, '').trim();
      if (!title || title.length < 5) continue;
      const authorMatch = block.match(authorRegex);
      const yearMatch = block.match(yearRegex);
      const revueMatch = block.match(revueRegex);
      const resumeMatch = block.match(resumeRegex);
      const author = authorMatch ? authorMatch[1].replace(/<[^>]*>/g, '').trim() : '';
      const year = yearMatch ? yearMatch[1] : '';
      const revue = revueMatch ? revueMatch[1].replace(/<[^>]*>/g, '').trim() : '';
      const resume = resumeMatch ? resumeMatch[1].replace(/<[^>]*>/g, '').trim() : '';
      const url = linkMatch ? 'https://www.cairn.info' + linkMatch[1] : searchUrl;
      results.push({
        title,
        source: 'Cairn.info',
        url,
        snippet: resume || (author ? author + '. ' : '') + title + (revue ? '. ' + revue : '') + (year ? ' (' + year + ')' : ''),
        date: year,
        language: 'fr',
        isPeerReviewed: !!revue,
        isMeta: title.toLowerCase().includes('méta-analyse') || title.toLowerCase().includes('revue systématique'),
        isGuideline: title.toLowerCase().includes('recommandation'),
        isCaseStudy: title.toLowerCase().includes('cas clinique') || title.toLowerCase().includes('étude de cas'),
        isTextbook: false,
        type: 'article',
        citationCount: null,
        doi: null
      });
    }
    // Fallback si le regex structuré ne trouve rien — parser les liens <a> avec titres
    if (results.length === 0) {
      const simpleRegex = /<a[^>]*href="(\/(?:revue|article)[^"]*)"[^>]*>\s*([^<]{10,100})\s*<\/a>/gi;
      let sm;
      while ((sm = simpleRegex.exec(html)) !== null && results.length < (maxResults || 5)) {
        const sTitle = sm[2].trim();
        const sUrl = 'https://www.cairn.info' + sm[1];
        if (results.some(r => r.title === sTitle)) continue;
        results.push({
          title: sTitle,
          source: 'Cairn.info',
          url: sUrl,
          snippet: sTitle,
          date: '',
          language: 'fr',
          isPeerReviewed: true,
          isMeta: false, isGuideline: false, isCaseStudy: false, isTextbook: false,
          type: 'article',
          citationCount: null, doi: null
        });
      }
    }
    console.log('[WebConsult] Cairn: ' + results.length + ' résultats parsés');
    return results;
  } catch (e) {
    console.error('[WebConsult] Cairn error:', e.message);
    return [];
  }
}
__name(searchCairn, "searchCairn");

function mergeAndDeduplicate(allSettled) {
  const seen = new Set();
  const results = [];
  for (const res of allSettled) {
    if (res.status !== 'fulfilled' || !Array.isArray(res.value)) continue;
    for (const item of res.value) {
      const key = (item.title || '').toLowerCase().replace(/[^a-z0-9]/g, '').substring(0, 60);
      if (key && seen.has(key)) continue;
      seen.add(key);
      const urlLower = (item.url || '').toLowerCase();
      if (TRUSTED_DOMAINS.excluded_patterns.some(p => urlLower.includes(p))) continue;
      results.push(item);
    }
  }
  results.sort((a, b) => {
    const aS = (a.isPeerReviewed ? 100 : 0) + (a.isMeta ? 50 : 0) + (parseInt(a.date) || 2000);
    const bS = (b.isPeerReviewed ? 100 : 0) + (b.isMeta ? 50 : 0) + (parseInt(b.date) || 2000);
    return bS - aS;
  });
  return results;
}
__name(mergeAndDeduplicate, "mergeAndDeduplicate");

async function logWebConsult(env2, caller, query, domain, resultCount) {
  if (!env2.DB) return;
  try {
    await env2.DB.prepare(
      'INSERT INTO web_consult_log (timestamp, caller, query, domain, result_count) VALUES (?, ?, ?, ?, ?)'
    ).bind(new Date().toISOString(), caller || 'unknown', (query || '').substring(0, 200), domain || 'general', resultCount || 0).run();
  } catch (_) { /* table optionnelle */ }
}
__name(logWebConsult, "logWebConsult");

async function handleWebConsult(request2, env2) {
  let body;
  try { body = await request2.json(); } catch { return jsonErr('Invalid JSON', 400); }
  const { query, domain = 'general', sources = ['pubmed','scholar','google_scholar'], language = 'fr', max_results = 5, caller = 'unknown' } = body;
  if (!query || typeof query !== 'string' || query.trim().length < 3) return jsonErr('Query required (min 3 chars)', 400);
  const cleanQuery = query.trim().substring(0, 300);
  try {
    const searchPromises = [];
    if (sources.includes('pubmed')) searchPromises.push(searchPubMed(cleanQuery, language, max_results));
    if (sources.includes('scholar')) searchPromises.push(searchSemanticScholar(cleanQuery, language, max_results));
    if (sources.includes('google_scholar')) searchPromises.push(searchGoogleScholar(cleanQuery, language, max_results, env2));
    // Cairn.info — désactivé (captcha anti-bot bloque les Workers CF)
    // Google Scholar couvre le catalogue Cairn via SerpApi
    // if (sources.includes('cairn')) searchPromises.push(searchCairn(cleanQuery, language, max_results));
    const allResults = await Promise.allSettled(searchPromises);
    const merged = mergeAndDeduplicate(allResults);
    const scored = merged.map(r => ({ ...r, reliability: scoreReliability(r), reliability_reason: explainReliability(r) }));
    const highMed = scored.filter(r => r.reliability !== 'low');
    const filtered = highMed.length >= 2 ? highMed.slice(0, max_results) : scored.slice(0, max_results);
    logWebConsult(env2, caller, cleanQuery, domain, filtered.length);
    return json({
      results: filtered.map(r => ({
        title: r.title, source: r.source, url: r.url,
        snippet: (r.snippet || '').substring(0, 500),
        date: r.date, reliability: r.reliability, reliability_reason: r.reliability_reason,
        domain, language: r.language || language, type: r.type,
        pmid: r.pmid || null, doi: r.doi || null, citationCount: r.citationCount || null
      })),
      meta: {
        query: cleanQuery, sources_consulted: sources,
        total_found: merged.length, returned: filtered.length,
        filtered_out: merged.length - filtered.length,
        timestamp: new Date().toISOString()
      }
    });
  } catch (err) {
    console.error('[WebConsult] Error:', err.message);
    return jsonErr('web-consult error: ' + err.message, 500);
  }
}
__name(handleWebConsult, "handleWebConsult");


// ═══ TTS GOOGLE — proxy vers Google Cloud Text-to-Speech ═══
async function handleTTSGoogle(request2, env2) {
  if (!env2.GOOGLE_TTS_KEY) {
    return new Response(JSON.stringify({ error: "Google TTS key not configured" }), {
      status: 500, headers: { "Content-Type": "application/json", ...CORS }
    });
  }
  let body;
  try { body = await request2.json(); } catch {
    return new Response(JSON.stringify({ error: "Invalid JSON" }), {
      status: 400, headers: { "Content-Type": "application/json", ...CORS }
    });
  }
  try {
    const r = await fetch(
      "https://texttospeech.googleapis.com/v1/text:synthesize?key=" + env2.GOOGLE_TTS_KEY,
      { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }
    );
    if (!r.ok) {
      const err = await r.text();
      return new Response(JSON.stringify({ error: "Google TTS error", status: r.status, detail: err }), {
        status: r.status, headers: { "Content-Type": "application/json", ...CORS }
      });
    }
    const data = await r.json();
    return new Response(JSON.stringify(data), {
      headers: { "Content-Type": "application/json", ...CORS }
    });
  } catch (e) {
    return new Response(JSON.stringify({ error: e.message }), {
      status: 500, headers: { "Content-Type": "application/json", ...CORS }
    });
  }
}
__name(handleTTSGoogle, "handleTTSGoogle");

// ═══ TTS OPENAI — proxy vers OpenAI Audio Speech ═══
async function handleTTSOpenAI(request2, env2) {
  if (!env2.OPENAI_API_KEY) {
    return new Response(JSON.stringify({ error: "OpenAI key not configured" }), {
      status: 500, headers: { "Content-Type": "application/json", ...CORS }
    });
  }
  let body;
  try { body = await request2.json(); } catch {
    return new Response(JSON.stringify({ error: "Invalid JSON" }), {
      status: 400, headers: { "Content-Type": "application/json", ...CORS }
    });
  }
  try {
    const r = await fetch("https://api.openai.com/v1/audio/speech", {
      method: "POST",
      headers: { "Content-Type": "application/json", "Authorization": "Bearer " + env2.OPENAI_API_KEY },
      body: JSON.stringify(body)
    });
    if (!r.ok) {
      const err = await r.text();
      return new Response(JSON.stringify({ error: "OpenAI TTS error", status: r.status, detail: err }), {
        status: r.status, headers: { "Content-Type": "application/json", ...CORS }
      });
    }
    const audioBuffer = await r.arrayBuffer();
    return new Response(audioBuffer, {
      headers: { "Content-Type": "audio/mpeg", ...CORS }
    });
  } catch (e) {
    return new Response(JSON.stringify({ error: e.message }), {
      status: 500, headers: { "Content-Type": "application/json", ...CORS }
    });
  }
}
__name(handleTTSOpenAI, "handleTTSOpenAI");

// ═══════════════════════════════════════════════════════════════════
// VOIX — énumération des catalogues + synthèse normalisée
//   GET  /voices?lang=fr-FR   catalogue agrégé
//   GET  /models              modèles OpenAI réellement actifs sur le compte
//   POST /speak               { provider, voice, text, model?, speed?, instructions? }
//                             renvoie TOUJOURS de l'audio/mpeg brut
// Secret optionnel : ELEVENLABS_API_KEY
// ═══════════════════════════════════════════════════════════════════

function voiceFamily(name) {
  const n = String(name).toLowerCase();
  const families = ["chirp3-hd", "chirp", "journey", "studio", "neural2", "wavenet", "polyglot", "news"];
  for (const f of families) if (n.includes(f)) return f;
  return "standard";
}
__name(voiceFamily, "voiceFamily");

async function handleVoicesList(url, env2) {
  const lang = url.searchParams.get("lang") || "fr-FR";
  const out = { lang, google: [], openai: [], elevenlabs: [], errors: {} };

  // Google — le seul fournisseur dont le catalogue s'interroge vraiment
  if (env2.GOOGLE_TTS_KEY) {
    try {
      const r = await fetch(
        "https://texttospeech.googleapis.com/v1/voices?languageCode=" +
        encodeURIComponent(lang) + "&key=" + env2.GOOGLE_TTS_KEY
      );
      const d = await r.json();
      if (!r.ok) throw new Error(d?.error?.message || ("HTTP " + r.status));
      out.google = (d.voices || []).map((v) => ({
        id: v.name,
        family: voiceFamily(v.name),
        gender: String(v.ssmlGender || "").toLowerCase(),
        sampleRate: v.naturalSampleRateHertz,
        languages: v.languageCodes
      })).sort((a, b) => a.family.localeCompare(b.family) || a.id.localeCompare(b.id));
    } catch (e) { out.errors.google = e.message; }
  } else {
    out.errors.google = "GOOGLE_TTS_KEY non configurée";
  }

  // OpenAI — pas d'endpoint /voices, la liste est fixe
  if (env2.OPENAI_API_KEY) {
    out.openai = ["alloy","ash","ballad","cedar","coral","echo","fable",
                  "marin","nova","onyx","sage","shimmer","verse"]
      .map((id) => ({ id, note: "disponibilité selon le modèle — voir /models" }));
  } else {
    out.errors.openai = "OPENAI_API_KEY non configurée";
  }

  // ElevenLabs — actif dès que le secret est posé
  if (env2.ELEVENLABS_API_KEY) {
    try {
      const r = await fetch("https://api.elevenlabs.io/v1/voices", {
        headers: { "xi-api-key": env2.ELEVENLABS_API_KEY }
      });
      const d = await r.json();
      if (!r.ok) throw new Error(d?.detail?.message || ("HTTP " + r.status));
      out.elevenlabs = (d.voices || []).map((v) => ({
        id: v.voice_id, name: v.name, category: v.category,
        labels: v.labels, preview: v.preview_url
      }));
    } catch (e) { out.errors.elevenlabs = e.message; }
  } else {
    out.errors.elevenlabs = "ELEVENLABS_API_KEY non configurée";
  }

  out.counts = {
    google: out.google.length,
    openai: out.openai.length,
    elevenlabs: out.elevenlabs.length
  };
  return json(out);
}
__name(handleVoicesList, "handleVoicesList");

// Source de vérité sur les modèles vivants : le compte, pas la documentation.
async function handleModelsList(env2) {
  if (!env2.OPENAI_API_KEY) return jsonErr("OPENAI_API_KEY non configurée", 500);
  const r = await fetch("https://api.openai.com/v1/models", {
    headers: { Authorization: "Bearer " + env2.OPENAI_API_KEY }
  });
  const d = await r.json();
  if (!r.ok) return jsonErr(d?.error?.message || ("HTTP " + r.status), r.status);
  const ids = (d.data || []).map((m) => m.id).sort();
  return json({
    realtime: ids.filter((i) => i.includes("realtime")),
    speech: ids.filter((i) => i.includes("tts") || i.includes("audio")),
    total: ids.length
  });
}
__name(handleModelsList, "handleModelsList");

async function handleSpeak(request2, env2) {
  let body;
  try { body = await request2.json(); } catch { return jsonErr("Invalid JSON", 400); }
  const { provider = "google", voice, text, model, speed = 1, instructions } = body;
  if (!text) return jsonErr("Champ 'text' manquant", 400);
  if (!voice) return jsonErr("Champ 'voice' manquant", 400);

  const audioHeaders = { ...CORS, "Content-Type": "audio/mpeg", "Cache-Control": "no-store" };

  if (provider === "google") {
    if (!env2.GOOGLE_TTS_KEY) return jsonErr("GOOGLE_TTS_KEY non configurée", 500);
    // Chirp 3 HD refuse ssmlGender et pitch
    const isChirp3 = String(voice).includes("Chirp3-HD");
    const languageCode = String(voice).split("-").slice(0, 2).join("-");
    const audioConfig = { audioEncoding: "MP3" };
    if (speed && speed !== 1) audioConfig.speakingRate = speed;
    const r = await fetch(
      "https://texttospeech.googleapis.com/v1/text:synthesize?key=" + env2.GOOGLE_TTS_KEY,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          input: { text },
          voice: isChirp3 ? { languageCode, name: voice } : { languageCode, name: voice },
          audioConfig
        })
      }
    );
    const d = await r.json();
    if (!r.ok) return json({ error: "Google TTS", detail: d }, r.status);
    // base64 -> octets, pour homogénéiser avec les autres fournisseurs
    const bin = atob(d.audioContent);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return new Response(bytes, { headers: audioHeaders });
  }

  if (provider === "openai") {
    if (!env2.OPENAI_API_KEY) return jsonErr("OPENAI_API_KEY non configurée", 500);
    const payload = {
      model: model || env2.OPENAI_TTS_MODEL || "gpt-4o-mini-tts",
      voice, input: text, speed, response_format: "mp3"
    };
    if (instructions) payload.instructions = instructions;
    const r = await fetch("https://api.openai.com/v1/audio/speech", {
      method: "POST",
      headers: { Authorization: "Bearer " + env2.OPENAI_API_KEY, "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
    if (!r.ok) return json({ error: "OpenAI TTS", detail: await r.text() }, r.status);
    return new Response(r.body, { headers: audioHeaders });
  }

  if (provider === "elevenlabs") {
    if (!env2.ELEVENLABS_API_KEY) return jsonErr("ELEVENLABS_API_KEY non configurée", 500);
    const r = await fetch(
      "https://api.elevenlabs.io/v1/text-to-speech/" + encodeURIComponent(voice) +
      "?output_format=mp3_44100_128",
      {
        method: "POST",
        headers: { "xi-api-key": env2.ELEVENLABS_API_KEY, "Content-Type": "application/json" },
        body: JSON.stringify({ text, model_id: model || "eleven_multilingual_v2" })
      }
    );
    if (!r.ok) return json({ error: "ElevenLabs", detail: await r.text() }, r.status);
    return new Response(r.body, { headers: audioHeaders });
  }

  return jsonErr("Fournisseur inconnu : " + provider, 400);
}
__name(handleSpeak, "handleSpeak");

